import type { VariantProps } from 'class-variance-authority'
import type { Accessor, JSX } from 'solid-js'
import { cva } from 'class-variance-authority'
import { animate, transform } from 'motion'
import {
  createContext,
  createEffect,
  createMemo,
  createSignal,
  mergeProps,
  onCleanup,
  splitProps,
  untrack,
  useContext,
} from 'solid-js'
import { cn } from '@/lib/utils'

export interface DockProps extends VariantProps<typeof dockVariants> {
  class?: string
  iconSize?: number
  iconMagnification?: number
  disableMagnification?: boolean
  iconDistance?: number
  direction?: 'top' | 'middle' | 'bottom'
  children: JSX.Element
  ref?: HTMLDivElement | ((el: HTMLDivElement) => void)
}

const DEFAULT_SIZE = 40
const DEFAULT_MAGNIFICATION = 60
const DEFAULT_DISTANCE = 140
const DEFAULT_DISABLEMAGNIFICATION = false

export const dockVariants = cva(
  `
    mx-auto mt-8 flex h-14.5 w-max items-center justify-center gap-2 rounded-2xl
    border p-2 backdrop-blur-md
    supports-backdrop-blur:bg-white/10
    supports-backdrop-blur:dark:bg-black/10
  `,
)

interface DockContextValue {
  mouseX: Accessor<number>
  iconSize: Accessor<number>
  iconMagnification: Accessor<number>
  disableMagnification: Accessor<boolean>
  iconDistance: Accessor<number>
}

const DockContext = createContext<DockContextValue>()

export function Dock(props: DockProps) {
  const merged = mergeProps(
    {
      iconSize: DEFAULT_SIZE,
      iconMagnification: DEFAULT_MAGNIFICATION,
      disableMagnification: DEFAULT_DISABLEMAGNIFICATION,
      iconDistance: DEFAULT_DISTANCE,
      direction: 'middle',
    },
    props,
  )
  const [local, rest] = splitProps(merged, [
    'class',
    'children',
    'iconSize',
    'iconMagnification',
    'disableMagnification',
    'iconDistance',
    'direction',
    'ref',
  ])
  const [mouseX, setMouseX] = createSignal(Infinity)

  const contextValue: DockContextValue = {
    mouseX,
    iconSize: () => local.iconSize,
    iconMagnification: () => local.iconMagnification,
    disableMagnification: () => local.disableMagnification,
    iconDistance: () => local.iconDistance,
  }

  return (
    <DockContext.Provider value={contextValue}>
      <div
        ref={local.ref}
        role="toolbar"
        onMouseMove={e => setMouseX(e.pageX)}
        onMouseLeave={() => setMouseX(Infinity)}
        {...rest}
        class={cn(dockVariants({ class: local.class }), {
          'items-start': local.direction === 'top',
          'items-center': local.direction === 'middle',
          'items-end': local.direction === 'bottom',
        })}
      >
        {local.children}
      </div>
    </DockContext.Provider>
  )
}

export interface DockIconProps extends Omit<JSX.HTMLAttributes<HTMLDivElement>, 'children'> {
  size?: number
  magnification?: number
  disableMagnification?: boolean
  distance?: number
  mouseX?: Accessor<number>
  class?: string
  children?: JSX.Element
}

export function DockIcon(props: DockIconProps) {
  const merged = mergeProps(
    {
      size: DEFAULT_SIZE,
      magnification: DEFAULT_MAGNIFICATION,
      distance: DEFAULT_DISTANCE,
    },
    props,
  )
  const [local, rest] = splitProps(merged, [
    'class',
    'children',
    'size',
    'magnification',
    'disableMagnification',
    'distance',
    'mouseX',
  ])
  const dockContext = useContext(DockContext)

  const [iconEl, setIconEl] = createSignal<HTMLDivElement>()

  const mouseX = () => dockContext ? dockContext.mouseX() : (local.mouseX?.() ?? Infinity)
  const iconSize = () => dockContext ? dockContext.iconSize() : local.size
  const magnification = () => dockContext ? dockContext.iconMagnification() : local.magnification
  const disableMagnification = () => dockContext ? dockContext.disableMagnification() : local.disableMagnification
  const iconDistance = () => dockContext ? dockContext.iconDistance() : local.distance
  const targetSize = () => disableMagnification() ? iconSize() : magnification()

  const sizeTransform = createMemo(() =>
    transform([-iconDistance(), 0, iconDistance()], [iconSize(), targetSize(), iconSize()]),
  )

  createEffect(() => {
    const el = iconEl()
    if (!el)
      return
    const bounds = el.getBoundingClientRect()
    const distance = mouseX() - bounds.x - bounds.width / 2
    const clamped = Math.max(-iconDistance(), Math.min(iconDistance(), distance))
    const target = sizeTransform()(clamped)
    const animation = animate(
      el,
      { width: target, height: target },
      {
        type: 'spring',
        mass: 0.1,
        stiffness: 150,
        damping: 12,
      },
    )
    onCleanup(() => animation.stop())
  })

  return (
    <div
      ref={setIconEl}
      style={{
        width: `${untrack(iconSize)}px`,
        height: `${untrack(iconSize)}px`,
        padding: `${Math.max(6, untrack(iconSize) * 0.2)}px`,
      }}
      class={cn(
        `
          flex aspect-square cursor-pointer items-center justify-center
          rounded-full
        `,
        disableMagnification() && `
          transition-colors
          hover:bg-muted-foreground
        `,
        local.class,
      )}
      {...rest}
    >
      <div>{local.children}</div>
    </div>
  )
}

src/registry/magicui/dot-pattern.tsx.content:
import type { JSX } from 'solid-js'
import { animate } from 'motion'
import {
  createEffect,
  createMemo,
  createSignal,
  createUniqueId,
  For,
  mergeProps,
  onCleanup,
  splitProps,
} from 'solid-js'
import { cn } from '@/lib/utils'

export interface DotPatternProps extends JSX.SvgSVGAttributes<SVGSVGElement> {
  width?: number
  height?: number
  x?: number
  y?: number
  cx?: number
  cy?: number
  cr?: number
  glow?: boolean
}

function PatternDot(props: { x: number, y: number, r: number, fill: string, delay: number, duration: number, glow: boolean }) {
  let ref: SVGCircleElement | undefined

  createEffect(() => {
    if (!props.glow || !ref)
      return
    const anim = animate(
      ref,
      {
        opacity: [0.4, 1, 0.4],
        scale: [1, 1.5, 1],
      },
      {
        duration: props.duration,
        repeat: Infinity,
        repeatType: 'reverse',
        delay: props.delay,
        ease: 'easeInOut',
      },
    )
    onCleanup(() => anim.stop())
  })

  return <circle ref={ref} cx={props.x} cy={props.y} r={props.r} fill={props.fill} />
}

/**
 * DotPattern Component
 *
 * A Solid component that creates an animated or static dot pattern background using SVG.
 * The pattern automatically adjusts to fill its container and can optionally display glowing dots.
 */
export function DotPattern(props: DotPatternProps) {
  const merged = mergeProps(
    { width: 16, height: 16, x: 0, y: 0, cx: 1, cy: 1, cr: 1, glow: false },
    props,
  )
  const [local, rest] = splitProps(merged, [
    'width',
    'height',
    'x',
    'y',
    'cx',
    'cy',
    'cr',
    'glow',
    'class',
  ])
  const id = createUniqueId()
  let svgRef: SVGSVGElement | undefined
  const [dimensions, setDimensions] = createSignal({ width: 0, height: 0 })

  createEffect(() => {
    if (!svgRef)
      return
    const updateDimensions = () => {
      if (svgRef) {
        const { width, height } = svgRef.getBoundingClientRect()
        setDimensions({ width, height })
      }
    }

    updateDimensions()
    window.addEventListener('resize', updateDimensions)
    onCleanup(() => window.removeEventListener('resize', updateDimensions))
  })

  const dots = createMemo(() => {
    const width = local.width
    const height = local.height
    const cx = local.cx
    const cy = local.cy
    const x = local.x
    const y = local.y
    const cols = Math.ceil(dimensions().width / width)
    const rows = Math.ceil(dimensions().height / height)
    return Array.from({ length: cols * rows }, (_, i) => {
      const col = i % cols
      const row = Math.floor(i / cols)
      return {
        x: col * width + cx + x,
        y: row * height + cy + y,
        delay: Math.random() * 5,
        duration: Math.random() * 3 + 2,
      }
    })
  })

  return (
    <svg
      ref={svgRef}
      aria-hidden="true"
      class={cn(
        'pointer-events-none absolute inset-0 size-full text-neutral-400/80',
        local.class,
      )}
      {...rest}
    >
      <defs>
        <radialGradient id={`${id}-gradient`}>
          <stop offset="0%" stop-color="currentColor" stop-opacity="1" />
          <stop offset="100%" stop-color="currentColor" stop-opacity="0" />
        </radialGradient>
      </defs>
      <For each={dots()}>
        {dot => (
          <PatternDot
            x={dot.x}
            y={dot.y}
            r={local.cr}
            fill={local.glow ? `url(#${id}-gradient)` : 'currentColor'}
            delay={dot.delay}
            duration={dot.duration}
            glow={local.glow}
          />
        )}
      </For>
    </svg>
  )
}

