import type { JSX, ValidComponent } from 'solid-js'
import { createEffect, createMemo, createSignal, For, mergeProps, onCleanup, splitProps } from 'solid-js'
import { Dynamic } from 'solid-js/web'
import { cn } from '@/lib/utils'

type CharacterSet = string[] | readonly string[]

interface HyperTextProps extends Omit<JSX.HTMLAttributes<HTMLElement>, 'children'> {
  /**
   * The text content to be animated
   */
  children: string
  /**
   * Optional class for styling
   */
  class?: string
  /**
   * Duration of the animation in milliseconds
   */
  duration?: number
  /**
   * Delay before animation starts in milliseconds
   */
  delay?: number
  /**
   * Component to render as - defaults to div
   */
  as?: ValidComponent
  /**
   * Whether to start animation when element comes into view
   */
  startOnView?: boolean
  /**
   * Whether to trigger animation on hover
   */
  animateOnHover?: boolean
  /**
   * Custom character set for scramble effect. Defaults to uppercase alphabet
   */
  characterSet?: CharacterSet
}

const DEFAULT_CHARACTER_SET = Object.freeze(
  'ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split(''),
) as readonly string[]

const getRandomInt = (max: number): number => Math.floor(Math.random() * max)

export function HyperText(props: HyperTextProps) {
  const merged = mergeProps(
    {
      duration: 800,
      delay: 0,
      as: 'div',
      startOnView: false,
      animateOnHover: true,
      characterSet: DEFAULT_CHARACTER_SET,
    } as const,
    props,
  )
  const [local, rest] = splitProps(merged, [
    'children',
    'class',
    'duration',
    'delay',
    'as',
    'startOnView',
    'animateOnHover',
    'characterSet',
  ])

  // Animation progress 0→1; 1 means idle/completed. Everything else is derived.
  const [progress, setProgress] = createSignal(1)
  let animationFrameId: number | null = null
  let elementRef: HTMLElement | undefined

  // Derived display text: reacts to children changes automatically and
  // re-randomizes scramble chars on every progress tick (same as the previous
  // per-frame map over the signal).
  const displayText = createMemo(() => {
    const chars = local.children.split('')
    const currentIter = progress() * chars.length
    return chars.map((char, index) =>
      char === ' '
        ? char
        : index <= currentIter
          ? char
          : local.characterSet[getRandomInt(local.characterSet.length)],
    )
  })

  const startAnimation = () => {
    if (animationFrameId !== null)
      return
    const startTime = performance.now()
    const tick = (currentTime: number) => {
      const next = Math.min((currentTime - startTime) / local.duration, 1)
      setProgress(next)
      animationFrameId = next < 1 ? requestAnimationFrame(tick) : null
    }
    animationFrameId = requestAnimationFrame(tick)
  }

  const handleAnimationTrigger = () => {
    if (local.animateOnHover && progress() === 1)
      startAnimation()
  }

  // Handle animation start based on view or delay
  createEffect(() => {
    if (!local.startOnView) {
      const startTimeout = setTimeout(startAnimation, local.delay)
      onCleanup(() => clearTimeout(startTimeout))
      return
    }

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setTimeout(() => {
            startAnimation()
          }, local.delay)
          observer.disconnect()
        }
      },
      { threshold: 0.1, rootMargin: '-30% 0px -30% 0px' },
    )

    if (elementRef)
      observer.observe(elementRef)

    onCleanup(() => observer.disconnect())
  })

  onCleanup(() => {
    if (animationFrameId !== null)
      cancelAnimationFrame(animationFrameId)
  })

  return (
    <Dynamic
      component={local.as}
      ref={elementRef}
      class={cn('overflow-hidden py-2 text-4xl font-bold', local.class)}
      onMouseEnter={handleAnimationTrigger}
      {...rest}
    >
      <For each={displayText()}>
        {letter => (
          <span class={cn('font-mono', letter === ' ' ? 'w-3' : '')}>
            {letter.toUpperCase()}
          </span>
        )}
      </For>
    </Dynamic>
  )
}

src/registry/magicui/icon-cloud.tsx.content:
import type { JSX } from 'solid-js'
import { Pause, Play } from 'lucide-solid'
import { createEffect, createSignal, onCleanup, Show } from 'solid-js'

import { Button } from '@/components/ui/button'

interface Icon {
  x: number
  y: number
  z: number
  scale: number
  opacity: number
  id: number
}

interface TargetRotation {
  x: number
  y: number
  startX: number
  startY: number
  distance: number
  startTime: number
  duration: number
}

interface IconCloudProps {
  icons?: JSX.Element[]
  images?: string[]
  showControl?: boolean
}

function easeOutCubic(t: number): number {
  return 1 - (1 - t) ** 3
}

export function IconCloud(props: IconCloudProps) {
  let canvas: HTMLCanvasElement | undefined
  const [iconPositions, setIconPositions] = createSignal<Icon[]>([])
  const [isDragging, setIsDragging] = createSignal(false)
  const [isPaused, setIsPaused] = createSignal(false)
  const [lastMousePos, setLastMousePos] = createSignal({ x: 0, y: 0 })
  const [mousePos, setMousePos] = createSignal({ x: 0, y: 0 })
  const [targetRotation, setTargetRotation] = createSignal<TargetRotation | null>(null)
  let animationFrame = 0
  let rotation = { x: 0, y: 0 }
  let iconCanvases: HTMLCanvasElement[] = []
  let imagesLoaded: boolean[] = []
  let hasContent = false
  const showControl = () => props.showControl ?? true

  // Pause animation if user prefers reduced motion
  createEffect(() => {
    const mediaQuery = window.matchMedia('(prefers-reduced-motion: reduce)')
    if (mediaQuery.matches)
      setIsPaused(true)

    const handleChange = (e: MediaQueryListEvent) => {
      setIsPaused(e.matches)
    }

    mediaQuery.addEventListener('change', handleChange)
    onCleanup(() => mediaQuery.removeEventListener('change', handleChange))
  })

  // Create icon canvases once when icons/images change
  createEffect(() => {
    const icons = props.icons
    const images = props.images
    hasContent = Boolean(icons || images)
    if (!icons && !images)
      return

    const items = icons ?? images ?? []
    imagesLoaded = Array.from<boolean>({ length: items.length }).fill(false)

    const newIconCanvases = items.map((item, index) => {
      const offscreen = document.createElement('canvas')
      offscreen.width = 40
      offscreen.height = 40
      const offCtx = offscreen.getContext('2d')

      if (offCtx) {
        if (images) {
          // Handle image URLs directly
          const img = new Image()
          img.crossOrigin = 'anonymous'
          img.src = items[index] as string
          img.onload = () => {
            offCtx.clearRect(0, 0, offscreen.width, offscreen.height)

            // Create circular clipping path
            offCtx.beginPath()
            offCtx.arc(20, 20, 20, 0, Math.PI * 2)
            offCtx.closePath()
            offCtx.clip()

            // Draw the image
            offCtx.drawImage(img, 0, 0, 40, 40)

            imagesLoaded[index] = true
          }
        }
        else {
          // Handle SVG icons: resolve Solid elements to actual DOM nodes
          const resolve = (el: unknown): Node | string => {
            if (typeof el === 'function')
              return resolve(el())
            if (el instanceof Node)
              return el
            return String(el)
          }
          const svgNode = resolve(item)
          if (svgNode instanceof Node) {
            const svgString = new XMLSerializer().serializeToString(svgNode)
            const img = new Image()
            img.src = `data:image/svg+xml;base64,${btoa(svgString)}`
            img.onload = () => {
              offCtx.scale(0.4, 0.4)
              offCtx.clearRect(0, 0, offscreen.width, offscreen.height)
              offCtx.drawImage(img, 0, 0)
              imagesLoaded[index] = true
            }
          }
        }
      }
      return offscreen
    })

    iconCanvases = newIconCanvases
  })

  // Generate initial icon positions on a sphere
  createEffect(() => {
    const icons = props.icons
    const images = props.images
    const items = icons ?? images ?? []
    const newIcons: Icon[] = []
    const numIcons = items.length || 20

    // Fibonacci sphere parameters
    const offset = 2 / numIcons
    const increment = Math.PI * (3 - Math.sqrt(5))

    for (let i = 0; i < numIcons; i++) {
      const y = i * offset - 1 + offset / 2
      const r = Math.sqrt(1 - y * y)
      const phi = i * increment

      const x = Math.cos(phi) * r
      const z = Math.sin(phi) * r

      newIcons.push({
        x: x * 100,
        y: y * 100,
        z: z * 100,
        scale: 1,
        opacity: 1,
        id: i,
      })
    }
    setIconPositions(newIcons)
  })

  // Handle mouse events
  const handleMouseDown = (e: MouseEvent) => {
    const rect = canvas?.getBoundingClientRect()
    if (!rect || !canvas)
      return

    const x = e.clientX - rect.left
    const y = e.clientY - rect.top

    const ctx = canvas.getContext('2d')
    if (!ctx)
      return

    iconPositions().forEach((icon) => {
      const cosX = Math.cos(rotation.x)
      const sinX = Math.sin(rotation.x)
      const cosY = Math.cos(rotation.y)
      const sinY = Math.sin(rotation.y)

      const rotatedX = icon.x * cosY - icon.z * sinY
      const rotatedZ = icon.x * sinY + icon.z * cosY
      const rotatedY = icon.y * cosX + rotatedZ * sinX

      const screenX = canvas.width / 2 + rotatedX
      const screenY = canvas.height / 2 + rotatedY

      const scale = (rotatedZ + 200) / 300
      const radius = 20 * scale
      const dx = x - screenX
      const dy = y - screenY

      if (dx * dx + dy * dy < radius * radius) {
        const targetX = -Math.atan2(
          icon.y,
          Math.sqrt(icon.x * icon.x + icon.z * icon.z),
        )
        const targetY = Math.atan2(icon.x, icon.z)

        const currentX = rotation.x
        const currentY = rotation.y
        const distance = Math.sqrt(
          (targetX - currentX) ** 2 + (targetY - currentY) ** 2,
        )

        const duration = Math.min(2000, Math.max(800, distance * 1000))

        setTargetRotation({
          x: targetX,
          y: targetY,
          startX: currentX,
          startY: currentY,
          distance,
          startTime: performance.now(),
          duration,
        })
      }
    })

    setIsDragging(true)
    setLastMousePos({ x: e.clientX, y: e.clientY })
  }

  const handleMouseMove = (e: MouseEvent) => {
    const rect = canvas?.getBoundingClientRect()
    if (rect) {
      const x = e.clientX - rect.left
      const y = e.clientY - rect.top
      setMousePos({ x, y })
    }

    if (isDragging()) {
      const deltaX = e.clientX - lastMousePos().x
      const deltaY = e.clientY - lastMousePos().y

      rotation = {
        x: rotation.x + deltaY * 0.002,
        y: rotation.y + deltaX * 0.002,
      }

      setLastMousePos({ x: e.clientX, y: e.clientY })
    }
  }

  const handleMouseUp = () => {
    setIsDragging(false)
  }

  // Animation and rendering
  createEffect(() => {
    const canvasEl = canvas
    const ctx = canvasEl?.getContext('2d')
    if (!canvasEl || !ctx)
      return

    const paused = isPaused()

    const animate = () => {
      ctx.clearRect(0, 0, canvasEl.width, canvasEl.height)

      const centerX = canvasEl.width / 2
      const centerY = canvasEl.height / 2
      const maxDistance = Math.sqrt(centerX * centerX + centerY * centerY)
      const dx = mousePos().x - centerX
      const dy = mousePos().y - centerY
      const distance = Math.sqrt(dx * dx + dy * dy)
      const speed = 0.003 + (distance / maxDistance) * 0.01

      const target = targetRotation()
      if (target) {
        const elapsed = performance.now() - target.startTime
        const progress = Math.min(1, elapsed / target.duration)
        const easedProgress = easeOutCubic(progress)

        rotation = {
          x: target.startX + (target.x - target.startX) * easedProgress,
          y: target.startY + (target.y - target.startY) * easedProgress,
        }

        if (progress >= 1) {
          setTargetRotation(null)
        }
      }
      else if (!isDragging() && !paused) {
        rotation = {
          x: rotation.x + (dy / canvasEl.height) * speed,
          y: rotation.y + (dx / canvasEl.width) * speed,
        }
      }

      iconPositions().forEach((icon, index) => {
        const cosX = Math.cos(rotation.x)
        const sinX = Math.sin(rotation.x)
        const cosY = Math.cos(rotation.y)
        const sinY = Math.sin(rotation.y)

        const rotatedX = icon.x * cosY - icon.z * sinY
        const rotatedZ = icon.x * sinY + icon.z * cosY
        const rotatedY = icon.y * cosX + rotatedZ * sinX

        const scale = (rotatedZ + 200) / 300
        const opacity = Math.max(0.2, Math.min(1, (rotatedZ + 150) / 200))

        ctx.save()
        ctx.translate(
          canvasEl.width / 2 + rotatedX,
          canvasEl.height / 2 + rotatedY,
        )
        ctx.scale(scale, scale)
        ctx.globalAlpha = opacity

        if (hasContent) {
          // Only try to render icons/images if they exist
          if (iconCanvases[index] && imagesLoaded[index]) {
            ctx.drawImage(iconCanvases[index], -20, -20, 40, 40)
          }
        }
        else {
          // Show numbered circles if no icons/images are provided
          ctx.beginPath()
          ctx.arc(0, 0, 20, 0, Math.PI * 2)
          ctx.fillStyle = '#4444ff'
          ctx.fill()
          ctx.fillStyle = 'white'
          ctx.textAlign = 'center'
          ctx.textBaseline = 'middle'
          ctx.font = '16px Arial'
          ctx.fillText(`${icon.id + 1}`, 0, 0)
        }

        ctx.restore()
      })

      const hasPendingAssets = hasContent && !imagesLoaded.every(loaded => loaded)
      const shouldContinue = !paused || isDragging() || targetRotation() !== null || hasPendingAssets
      if (shouldContinue)
        animationFrame = requestAnimationFrame(animate)
    }

    animationFrame = requestAnimationFrame(animate)
    onCleanup(() => cancelAnimationFrame(animationFrame))
  })

  return (
    <div class="relative inline-block">
      <canvas
        ref={canvas}
        width={400}
