import type { JSX } from 'solid-js'
import { animate } from 'motion'
import {
  createEffect,
  createMemo,
  createSignal,
  onCleanup,
  onMount,
  splitProps,
} from 'solid-js'
import { cn } from '@/lib/utils'

export function Pointer(props: JSX.HTMLAttributes<HTMLDivElement>) {
  const [local, rest] = splitProps(props, ['class', 'style', 'children'])

  const [x, setX] = createSignal(0)
  const [y, setY] = createSignal(0)
  const [isActive, setIsActive] = createSignal(false)
  const [pointerEl, setPointerEl] = createSignal<HTMLDivElement>()

  let containerEl: HTMLDivElement | undefined

  onMount(() => {
    const parentElement = containerEl?.parentElement ?? null
    if (!parentElement)
      return

    const handleMouseMove = (e: MouseEvent) => {
      setX(e.clientX)
      setY(e.clientY)
      setIsActive(true)
    }

    const handleMouseEnter = (e: MouseEvent) => {
      setX(e.clientX)
      setY(e.clientY)
      setIsActive(true)
    }

    const handleMouseLeave = () => {
      setIsActive(false)
    }

    parentElement.style.cursor = 'none'
    parentElement.addEventListener('mousemove', handleMouseMove)
    parentElement.addEventListener('mouseenter', handleMouseEnter)
    parentElement.addEventListener('mouseleave', handleMouseLeave)

    onCleanup(() => {
      parentElement.style.cursor = ''
      parentElement.removeEventListener('mousemove', handleMouseMove)
      parentElement.removeEventListener('mouseenter', handleMouseEnter)
      parentElement.removeEventListener('mouseleave', handleMouseLeave)
    })
  })

  createEffect(() => {
    const el = pointerEl()
    if (!el)
      return

    if (isActive()) {
      const anim = animate(
        el,
        { scale: [0, 1], opacity: [0, 1] },
        { duration: 0.3 },
      )
      onCleanup(() => anim.stop())
    }
    else {
      const anim = animate(
        el,
        { scale: 0, opacity: 0 },
        { duration: 0.3 },
      )
      onCleanup(() => anim.stop())
    }
  })

  const pointerPositionStyle = createMemo<JSX.CSSProperties>(() => ({
    top: `${y()}px`,
    left: `${x()}px`,
    ...(typeof local.style === 'object' ? local.style : {}),
  }))

  return (
    <>
      <div ref={containerEl} />
      <div
        class="pointer-events-none fixed z-50"
        style={pointerPositionStyle()}
        {...rest}
      >
        <div style={{ transform: 'translate(-50%, -50%)' }}>
          <div ref={setPointerEl} style={{ opacity: 0, transform: 'scale(0)' }}>
            {local.children || (
              <svg
                stroke="currentColor"
                fill="currentColor"
                stroke-width="1"
                viewBox="0 0 16 16"
                height="24"
                width="24"
                xmlns="http://www.w3.org/2000/svg"
                class={cn('rotate-[-70deg] stroke-white text-black', local.class)}
              >
                <path d="M14.082 2.182a.5.5 0 0 1 .103.557L8.528 15.467a.5.5 0 0 1-.917-.007L5.57 10.694.803 8.652a.5.5 0 0 1-.006-.916l12.728-5.657a.5.5 0 0 1 .556.103z" />
              </svg>
            )}
          </div>
        </div>
      </div>
    </>
  )
}

src/registry/magicui/progressive-blur.ts.content:
import type { JSX } from 'solid-js'
import { For, mergeProps } from 'solid-js'
import { cn } from '~/lib/utils'

export interface ProgressiveBlurProps {
  class?: string
  height?: string
  position?: 'top' | 'bottom' | 'both'
  blurLevels?: number[]
  children?: JSX.Element
}

const DEFAULT_BLUR_LEVELS = [0.5, 1, 2, 4, 8, 16, 32, 64]

const positionClass = {
  top: 'top-0',
  bottom: 'bottom-0',
  both: 'inset-y-0',
}

export function ProgressiveBlur(props: ProgressiveBlurProps) {
  const merged = mergeProps(
    { height: '30%', position: 'bottom' as const, blurLevels: DEFAULT_BLUR_LEVELS },
    props,
  )

  const maskImage = (index: number): string => {
    if (merged.position === 'both')
      return 'linear-gradient(rgba(0,0,0,0) 0%, rgba(0,0,0,1) 5%, rgba(0,0,0,1) 95%, rgba(0,0,0,0) 100%)'

    const direction = merged.position === 'top' ? 'to top' : 'to bottom'
    if (index === merged.blurLevels!.length - 1)
      return `linear-gradient(${direction}, rgba(0,0,0,0) 87.5%, rgba(0,0,0,1) 100%)`

    return `linear-gradient(${direction}, rgba(0,0,0,0) ${index * 12.5}%, rgba(0,0,0,1) ${(index + 1) * 12.5}%, rgba(0,0,0,1) ${(index + 2) * 12.5}%, rgba(0,0,0,0) ${(index + 3) * 12.5}%)`
  }

  const blurStyle = (level: number, index: number): JSX.CSSProperties => ({
    'z-index': String(index + 1),
    'backdrop-filter': `blur(${level}px)`,
    '-webkit-backdrop-filter': `blur(${level}px)`,
    'mask-image': maskImage(index),
    '-webkit-mask-image': maskImage(index),
  })

  return (
    <div
      class={cn(
        'pointer-events-none absolute inset-x-0 z-10',
        merged.class,
        positionClass[merged.position],
      )}
      style={{ height: merged.position === 'both' ? '100%' : merged.height }}
    >
      <For each={merged.blurLevels}>
        {(level, index) => (
          <div
            class="absolute inset-0"
            style={blurStyle(level, index())}
          />
        )}
      </For>
    </div>
  )
}

src/registry/magicui/pulsating-button.ts.content:
import type { JSX } from 'solid-js'
import { createEffect, mergeProps, onCleanup, splitProps } from 'solid-js'

import { cn } from '@/lib/utils'

interface PulsatingButtonProps extends JSX.ButtonHTMLAttributes<HTMLButtonElement> {
  class?: string
  children?: JSX.Element
  pulseColor?: string
  duration?: string
  distance?: string
  variant?: 'pulse' | 'ripple'
  ref?: (el: HTMLButtonElement) => void
}

export function PulsatingButton(props: PulsatingButtonProps) {
  const merged = mergeProps(
    {
      duration: '1.5s',
      distance: '8px',
      variant: 'pulse' as const,
    },
    props,
  )
  const [local, rest] = splitProps(merged, [
    'class',
    'children',
    'pulseColor',
    'duration',
    'distance',
    'variant',
    'ref',
  ])

  let innerRef: HTMLButtonElement | undefined

  createEffect(() => {
    if (!innerRef)
      return
    local.ref?.(innerRef)

    if (local.pulseColor) {
      innerRef.style.removeProperty('--bg')
      return
    }

    let animationFrameId = 0
    let currentBg = ''

    const updateBg = () => {
