  return new Float32Array([
    pixel[0] / 255,
    pixel[1] / 255,
    pixel[2] / 255,
    pixel[3] / 255,
  ])
}

function createFallbackGridStyle(
  cellSize: number,
  lineColor: string,
): JSX.CSSProperties {
  return {
    'animation': `${FALLBACK_ANIMATION_NAME} ${ANIMATION_DURATION_SECONDS}s linear infinite`,
    'background-image': `linear-gradient(to right, ${lineColor} 1px, transparent 0), linear-gradient(to bottom, ${lineColor} 1px, transparent 0)`,
    'background-repeat': 'repeat',
    'background-size': `${cellSize}px ${cellSize}px`,
    'transform': 'translateY(-50%)',
  }
