export function RetroGrid(props: RetroGridProps) {
  const merged = mergeProps(
    {
      angle: 65,
      cellSize: 60,
      opacity: 0.5,
      lightLineColor: 'gray',
      darkLineColor: 'gray',
    },
    props,
  )
  const [local, rest] = splitProps(merged, [
    'angle',
    'cellSize',
    'opacity',
    'lightLineColor',
    'darkLineColor',
    'class',
    'style',
  ])
